TURN = re.compile(r"\[(\S+)\] (\w+): (.*)")

def exchanges(text, asker="Customer"):
    ex = [[]]
    for t, who, said in TURN.findall(text):
        asked = any(w == asker
                    for _, w, _ in ex[-1])
        if (who == asker and asked
                and ex[-1][-1][1] != asker):
            ex.append([])  # {{next question}}
        ex[-1].append((t, who, said))
    if {w for _, w, _ in ex[-1]} == {asker}:
        tail = ex.pop()
        ex[-1] += tail  # "Great, thanks."
    return ex

